pub(crate) fn push_rag_where(
    qb: &mut sqlx::QueryBuilder<'_, sqlx::Postgres>,
    w: &crate::reference::RagWhereInput,
) -> bool {
    let mut any = false;
    if let Some(f) = &w.id {
        if any {
            qb.push(" AND ");
        }
        any = true;
        crate::engine::sqlx_postgres::filters::push_string_filter(qb, "id", f);
    }
    if let Some(f) = &w.text {
        if any {
            qb.push(" AND ");
        }
        any = true;
        crate::engine::sqlx_postgres::filters::push_string_filter(qb, "text", f);
    }
    if let Some(f) = &w.metadata {
        if any {
            qb.push(" AND ");
        }
        any = true;
        crate::engine::sqlx_postgres::filters::push_json_filter(qb, "metadata", f);
    }
    if let Some(f) = &w.created_at {
        if any {
            qb.push(" AND ");
        }
        any = true;
        crate::engine::sqlx_postgres::filters::push_datetime_filter(qb, "created_at", f);
    }
    if let Some(f) = &w.updated_at {
        if any {
            qb.push(" AND ");
        }
        any = true;
        crate::engine::sqlx_postgres::filters::push_datetime_filter(qb, "updated_at", f);
    }
    if let Some(f) = &w.firm_id {
        if any {
            qb.push(" AND ");
        }
        any = true;
        crate::engine::sqlx_postgres::filters::push_string_filter(qb, "firm_id", f);
    }
    if let Some(f) = &w.document_id {
        if any {
            qb.push(" AND ");
        }
        any = true;
        crate::engine::sqlx_postgres::filters::push_string_filter(qb, "document_id", f);
    }
    if let Some(f) = &w.case_id {
        if any {
            qb.push(" AND ");
        }
        any = true;
        crate::engine::sqlx_postgres::filters::push_string_filter(qb, "case_id", f);
    }
    if let Some(f) = &w.file_name {
        if any {
            qb.push(" AND ");
        }
        any = true;
        crate::engine::sqlx_postgres::filters::push_string_filter(qb, "file_name", f);
    }
    if let Some(f) = &w.document_type {
        if any {
            qb.push(" AND ");
        }
        any = true;
        crate::engine::sqlx_postgres::filters::push_string_filter(qb, "document_type", f);
    }
    if let Some(f) = &w.file_type {
        if any {
            qb.push(" AND ");
        }
        any = true;
        crate::engine::sqlx_postgres::filters::push_string_filter(qb, "file_type", f);
    }
    if let Some(f) = &w.content_type {
        if any {
            qb.push(" AND ");
        }
        any = true;
        crate::engine::sqlx_postgres::filters::push_string_filter(qb, "content_type", f);
    }
    if let Some(f) = &w.page_number {
        if any {
            qb.push(" AND ");
        }
        any = true;
        crate::engine::sqlx_postgres::filters::push_string_filter(qb, "page_number", f);
    }
    if let Some(f) = &w.chunk_type {
        if any {
            qb.push(" AND ");
        }
        any = true;
        crate::engine::sqlx_postgres::filters::push_string_filter(qb, "chunk_type", f);
    }
    if let Some(f) = &w.chunk_index {
        if any {
            qb.push(" AND ");
        }
        any = true;
        crate::engine::sqlx_postgres::filters::push_int_filter(qb, "chunk_index", f);
    }
    if let Some(f) = &w.parent_id {
        if any {
            qb.push(" AND ");
        }
        any = true;
        crate::engine::sqlx_postgres::filters::push_string_nullable_filter(qb, "parent_id", f);
    }
    if let Some(f) = &w.token_count {
        if any {
            qb.push(" AND ");
        }
        any = true;
        crate::engine::sqlx_postgres::filters::push_int_nullable_filter(qb, "token_count", f);
    }
    if let Some(rel) = &w.parent {
        if let Some(sub) = &rel.is {
            if any {
                qb.push(" AND ");
            }
            any = true;
            qb.push("EXISTS (SELECT 1 FROM \"cardozo_knowledge_bases\" t WHERE t.\"id\" = \"cardozo_knowledge_bases\".\"parent_id\" AND (");
            if !crate::engine::sqlx_postgres::reference::push_rag_where(qb, sub) {
                qb.push("TRUE");
            }
            qb.push("))");
        }
        if let Some(sub) = &rel.is_not {
            if any {
                qb.push(" AND ");
            }
            any = true;
            qb.push("NOT EXISTS (SELECT 1 FROM \"cardozo_knowledge_bases\" t WHERE t.\"id\" = \"cardozo_knowledge_bases\".\"parent_id\" AND (");
            if !crate::engine::sqlx_postgres::reference::push_rag_where(qb, sub) {
                qb.push("TRUE");
            }
            qb.push("))");
        }
    }
    if let Some(rel) = &w.children {
        if let Some(sub) = &rel.every {
            if any {
                qb.push(" AND ");
            }
            any = true;
            qb.push("NOT EXISTS (SELECT 1 FROM \"cardozo_knowledge_bases\" t WHERE t.\"parent_id\" = \"cardozo_knowledge_bases\".\"id\" AND NOT (");
            if !crate::engine::sqlx_postgres::reference::push_rag_where(qb, sub) {
                qb.push("TRUE");
            }
            qb.push("))");
        }
        if let Some(sub) = &rel.some {
            if any {
                qb.push(" AND ");
            }
            any = true;
            qb.push("EXISTS (SELECT 1 FROM \"cardozo_knowledge_bases\" t WHERE t.\"parent_id\" = \"cardozo_knowledge_bases\".\"id\" AND (");
            if !crate::engine::sqlx_postgres::reference::push_rag_where(qb, sub) {
                qb.push("TRUE");
            }
            qb.push("))");
        }
        if let Some(sub) = &rel.none {
            if any {
                qb.push(" AND ");
            }
            any = true;
            qb.push("NOT EXISTS (SELECT 1 FROM \"cardozo_knowledge_bases\" t WHERE t.\"parent_id\" = \"cardozo_knowledge_bases\".\"id\" AND (");
            if !crate::engine::sqlx_postgres::reference::push_rag_where(qb, sub) {
                qb.push("TRUE");
            }
            qb.push("))");
        }
    }
    if let Some(group) = &w.and {
        for sub in group {
            if any {
                qb.push(" AND ");
            }
            any = true;
            qb.push("(");
            if !push_rag_where(qb, sub) {
                qb.push("TRUE");
            }
            qb.push(")");
        }
    }
    if let Some(group) = &w.or {
        if any {
            qb.push(" AND ");
        }
        any = true;
        qb.push("(");
        let mut first = true;
        for sub in group {
            if !first {
                qb.push(" OR ");
            }
            first = false;
            qb.push("(");
            if !push_rag_where(qb, sub) {
                qb.push("TRUE");
            }
            qb.push(")");
        }
        qb.push(")");
    }
    if let Some(group) = &w.not {
        for sub in group {
            if any {
                qb.push(" AND ");
            }
            any = true;
            qb.push("NOT (");
            if !push_rag_where(qb, sub) {
                qb.push("TRUE");
            }
            qb.push(")");
        }
    }
    any
}

impl crate::reference::Rag {
    pub async fn find_unique<'e, E>(
        executor: E,
        w: &crate::reference::RagWhereUniqueInput,
    ) -> sqlx::Result<Option<Self>>
    where
        E: sqlx::Executor<'e, Database = sqlx::Postgres>,
    {
        let cols = "\"id\", \"text\", \"metadata\", \"created_at\", \"updated_at\", \"firm_id\", \"document_id\", \"case_id\", \"file_name\", \"document_type\", \"file_type\", \"content_type\", \"page_number\", \"chunk_type\", \"chunk_index\", \"parent_id\", \"token_count\"";
        let mut qb = sqlx::QueryBuilder::new(format!(
            r#"SELECT {} FROM "cardozo_knowledge_bases" WHERE "#,
            cols,
        ));
        // For v1, support only the @id field. Composite uniques are out of scope.
        // The WhereUniqueInput has Option<T> per @id/@unique field; we pick the
        // first Some(). Multi-Some inputs cover composite uniques — TODO Task v2.
        if let Some(value) = &w.id {
            qb.push("\"id\" = ");
            qb.push_bind(value.clone());
        } else {
            return Ok(None);
        }
        qb.build_query_as::<Self>().fetch_optional(executor).await
    }
}

